// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('locked_element_remains_selectable', async ({ page }) => {
    test.setTimeout(60000);

    const errors: Error[] = [];
    page.on('pageerror', (e) => errors.push(e));

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');

    // Draw a rectangle and lock it
    await page.getByTestId("toolbar-rectangle").click();
    await page.mouse.move(400, 220);
    await page.mouse.down();
    await page.mouse.move(520, 300, { steps: 10 });
    await page.mouse.up();
    await page.waitForTimeout(300);

    // Draw a second unlocked shape (diamond)
    await page.getByTestId("toolbar-diamond").click();
    await page.mouse.move(630, 220);
    await page.mouse.down();
    await page.mouse.move(750, 300, { steps: 10 });
    await page.mouse.up();
    await page.waitForTimeout(300);

    // Select and lock the rectangle
    await page.locator("body").click({ position: {"x": 460, "y": 218} });
    await page.waitForTimeout(200);
    await page.keyboard.press("Control+Shift+L");
    await page.waitForTimeout(200);

    // Select all and delete — unlocked diamond deleted, locked rectangle preserved
    await page.keyboard.press("Control+a");
    await page.keyboard.press("Delete");
    await page.waitForTimeout(500);

    // Click empty canvas to deselect everything
    await page.locator("body").click({ position: {"x": 700, "y": 450} });
    await page.waitForTimeout(300);

    // Click the locked rectangle's position — it must still be selectable
    await page.locator("body").click({ position: {"x": 460, "y": 218} });
    await page.waitForTimeout(300);

    // The 'Unlock' button appears when a locked element is selected — its presence proves
    // the locked element survived AND can be re-selected after the delete operation
    await expect(page.getByRole('generic', { name: 'Unlock' })).toBeVisible();

    expect(errors).toHaveLength(0);
});
